    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Tensión de Compuerta V_GS",
        "pregunta": "Calcule la tensión continua en la compuerta $V_{GS} = V_{DD} \\cdot \\frac{R_2}{R_1 + R_2}$ (en V).",
        "pistas": [
          "Pista 1: La impedancia de compuerta del MOSFET es prácticamente infinita ($I_G = 0$).",
          "Pista 2: Divisor resistivo directo: $V_G = 15\\text{ V} \\cdot \\frac{50}{100 + 50}$.",
          "Pista 3: $15\\text{ V} \\cdot \\frac{1}{3} = 5.0\\text{ V}$."
        ],
        "explicacion": "$V_{GS} = V_G = 15\\text{ V} \\cdot \\frac{50\\text{ k}\\Omega}{150\\text{ k}\\Omega} = 5.0\\text{ V}$. Como $V_{GS} = 5\\text{ V} > V_{TH} = 1.5\\text{ V}$, el canal está formado y conduce.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 5.0,
        "valorEsperado": 5.0,
        "tolerancia": 0.05,
        "simbolo": "V_{GS}",
        "explicacionPaso": "$V_{GS} = 15 \\cdot \\frac{50}{150} = 5.00\\text{ V}$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Corriente de reposo I_DQ",
        "pregunta": "Determine la corriente de drenaje $I_{DQ} = \\frac{1}{2} k_n (V_{GS} - V_{TH})^2$ en saturación (en mA).",
        "pistas": [
          "Pista 1: La sobretensión de compuerta es $V_{OV} = V_{GS} - V_{TH} = 5.0 - 1.5 = 3.5\\text{ V}$.",
          "Pista 2: $(V_{OV})^2 = (3.5)^2 = 12.25\\text{ V}^2$.",
          "Pista 3: $I_{DQ} = 0.5 \\cdot 1.0\\text{ mA/V}^2 \\cdot 12.25 = 6.125\\text{ mA}$."
        ],
        "explicacion": "$I_{DQ} = \\frac{1}{2} (1.0\\text{ mA/V}^2) (5.0\\text{ V} - 1.5\\text{ V})^2 = 0.5 \\cdot 12.25 = 6.125\\text{ mA} \\approx 6.13\\text{ mA}$.",
        "tipoRespuesta": "numerica",
        "unidad": "mA",
        "solucion": 6.13,
        "valorEsperado": 6.13,
        "tolerancia": 0.05,
        "simbolo": "I_{DQ}",
        "explicacionPaso": "$I_{DQ} = 0.5 \\cdot 1.0 \\cdot (3.5)^2 = 6.125\\text{ mA}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Ganancia de Tensión A_v",
        "pregunta": "Determine la ganancia de tensión en pequeña señal $A_v = -g_m R_D$ (en V/V).",
        "pistas": [
          "Pista 1: Calcule la transconductancia: $g_m = k_n (V_{GS} - V_{TH}) = 1.0\\text{ mA/V}^2 \\cdot 3.5\\text{ V} = 3.5\\text{ mS}$.",
          "Pista 2: $A_v = -g_m R_D = -(3.5\\text{ mS}) \\cdot (3.3\\text{ k}\\Omega)$.",
          "Pista 3: $-(3.5 \\cdot 3.3) = -11.55$."
        ],
        "explicacion": "$g_m = k_n (V_{GS} - V_{TH}) = 3.5\\text{ mS}$. La ganancia en Fuente Común es inversora: $A_v = -g_m R_D = -3.5\\text{ mS} \\cdot 3.3\\text{ k}\\Omega = -11.55\\text{ V/V}$.",
        "tipoRespuesta": "numerica",
        "unidad": "V/V",
        "solucion": -11.55,
        "valorEsperado": -11.55,
        "tolerancia": 0.05,
        "simbolo": "A_v",
        "explicacionPaso": "$A_v = -3.5\\text{ mS} \\cdot 3.3\\text{ k}\\Omega = -11.55\\text{ V/V}$."
      }
    ]
